}

static av_always_inline av_const unsigned av_mod_uintp2_c(unsigned a, unsigned p) /* <=== av_mod_uintp2_c */ 
{
    return a & ((1 << p) - 1);
}

static av_always_inline void bytestream2_skip(GetByteContext *g, /* <=== bytestream2_skip */ 
                                              unsigned int size)
{
    g->buffer += FFMIN(g->buffer_end - g->buffer, size);
}

